import { useCallback, useState } from "react";
import { SEARCH } from "../content/search";
import { explainAlert } from "../services/alertsService";

/** The explanation itself is generated by the API, which also owns the fallback wording. */
export default function useAlertExplanation() {
  const [openRecordId, setOpenRecordId] = useState(null);
  const [explanation, setExplanation] = useState(null);
  const [pendingRecordId, setPendingRecordId] = useState(null);

  const explain = useCallback(async (alert) => {
    setPendingRecordId(alert.record_id);
    setOpenRecordId(alert.record_id);
    setExplanation(null);
    try {
      setExplanation(await explainAlert(alert.record_id));
    } catch {
      setExplanation(SEARCH.explanation.failed);
    } finally {
      setPendingRecordId(null);
    }
  }, []);

  const close = useCallback(() => {
    setExplanation(null);
    setOpenRecordId(null);
  }, []);

  return { openRecordId, explanation, pendingRecordId, explain, close };
}
